/**
 * Run end-of-turn prediction on mono 16 kHz int16 PCM.
 *
 * Inputs shorter than 1.2 s (19200 samples) are left-padded with silence;
 * longer inputs are right-aligned-truncated. Returns a sigmoid probability
 * in [0, 1] that the user's turn just ended.
 *
 * Runs on libuv's worker thread pool, so the main event loop stays responsive
 * during the ~10 ms inference.
 */
export function predict(pcm: Int16Array): Promise<number>;

/**
 * Streaming voice-activity detector (16 kHz).
 * One instance per audio stream / speaker; the LSTM state lives on the
 * returned handle and persists across calls until `reset()` or GC.
 *
 * `predict(pcm)` MUST receive exactly `VAD_WINDOW_SAMPLES` int16 samples
 * (512 = 32 ms @ 16 kHz). Returns sigmoid voice probability in [0, 1].
 */
export interface Vad {
  predict(pcm: Int16Array): Promise<number>;
  reset(): void;
}
export function createVad(): Vad;
export const VAD_WINDOW_SAMPLES: number;

/**
 * Eagerly initialize the EOT model singleton (~108 MB). Call from a
 * prewarm hook so the load doesn't happen on the request path.
 * Idempotent; the first `predict()` calls this implicitly.
 */
export function initEot(): void;

/**
 * Eagerly initialize the VAD model singleton. Prewarm counterpart to
 * `initEot()`. Idempotent; the first `createVad()` calls this
 * implicitly.
 */
export function initVad(): void;
